from rules import solve_versions


def solve(data):
    return solve_versions(data)

def _active_deps(row, features):
    for dep in row.get('deps', []):
        feature = dep.get('feature')
        if feature and feature not in features:
            continue
        yield dep


def _is_acyclic(installed, rows, features):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dep in _active_deps(rows[name], features):
            target = dep['name']
            if target not in installed or not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in installed)


def solve_versions(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))

    # Include referenced names so that a missing dependency is represented
    # explicitly as having no installable version.
    names = set(packages) | set(roots)
    for package_rows in packages.values():
        for row in package_rows:
            for dep in row.get('deps', []):
                names.add(dep['name'])
    names = sorted(names)

    # A package outside this over-approximation of root reachability can never
    # belong to the exact dependency closure.
    possible = set(roots)
    pending = list(roots)
    while pending:
        name = pending.pop()
        for row in packages.get(name, []):
            for dep in _active_deps(row, features):
                target = dep['name']
                if target not in possible:
                    possible.add(target)
                    pending.append(target)

    domains = {}
    for name in names:
        versions = []
        root_range = roots.get(name)
        forbidden = set(blocked.get(name, []))
        for row in packages.get(name, []):
            version = row['version']
            if version in forbidden:
                continue
            if root_range is not None and not (root_range[0] <= version <= root_range[1]):
                continue
            if name in pins and version != pins[name]:
                continue
            versions.append((version, row))
        versions.sort(key=lambda item: item[0], reverse=True)
        if name not in possible and name not in roots:
            domains[name] = [None]
        else:
            domains[name] = versions
            if name not in roots:
                domains[name].append(None)

    assignment = {}
    selected_rows = {}

    def partial_ok():
        for name, choice in assignment.items():
            if choice is None:
                if name in roots:
                    return False
                continue
            version, row = choice
            for dep in _active_deps(row, features):
                target = dep['name']
                low, high = dep['min'], dep['max']
                if target in assignment:
                    target_choice = assignment[target]
                    if target_choice is None or not (low <= target_choice[0] <= high):
                        return False
                elif not any(candidate is not None and low <= candidate[0] <= high
                             for candidate in domains.get(target, [])):
                    return False
        return True

    def complete_ok():
        installed = {name for name, choice in assignment.items() if choice is not None}
        reached = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reached:
                continue
            if name not in installed:
                return False
            reached.add(name)
            for dep in _active_deps(selected_rows[name], features):
                target = dep['name']
                if target not in installed:
                    return False
                pending.append(target)
        return reached == installed and _is_acyclic(installed, selected_rows, features)

    def search(index):
        if index == len(names):
            return complete_ok()
        name = names[index]
        for choice in domains[name]:
            assignment[name] = choice
            if choice is not None:
                selected_rows[name] = choice[1]
            else:
                selected_rows.pop(name, None)
            if partial_ok() and search(index + 1):
                return True
        assignment.pop(name, None)
        selected_rows.pop(name, None)
        return False

    if not search(0):
        return {'error': 'unsatisfiable'}
    return {'versions': {name: assignment[name][0]
                         for name in names if assignment[name] is not None}}
